function rotl(x: number, n: number) {
  return (x << n) | (x >>> (32 - n))
}

function fn1(a: number, b: number, c: number, d: number, e: number, m: number, k: number, s: number) {
  return (rotl((a + (b ^ c ^ d) + m + k) | 0, s) + e) | 0
}

function fn2(a: number, b: number, c: number, d: number, e: number, m: number, k: number, s: number) {
  return (rotl((a + ((b & c) | (~b & d)) + m + k) | 0, s) + e) | 0
}

function fn3(a: number, b: number, c: number, d: number, e: number, m: number, k: number, s: number) {
  return (rotl((a + ((b | ~c) ^ d) + m + k) | 0, s) + e) | 0
}

function fn4(a: number, b: number, c: number, d: number, e: number, m: number, k: number, s: number) {
  return (rotl((a + ((b & d) | (c & ~d)) + m + k) | 0, s) + e) | 0
}

function fn5(a: number, b: number, c: number, d: number, e: number, m: number, k: number, s: number) {
  return (rotl((a + (b ^ (c | ~d)) + m + k) | 0, s) + e) | 0
}

export class Ripemd160 {
  // state
  private _a = 0x67452301
  private _b = 0xefcdab89
  private _c = 0x98badcfe
  private _d = 0x10325476
  private _e = 0xc3d2e1f0
  private _blockOffset = 0
  private _block: Uint8Array
  private _blockSize: number
  private _length = [0, 0, 0, 0]
  private _finalized: boolean

  constructor(blockSize = 64) {
    this._block = new Uint8Array(blockSize)
    this._blockSize = blockSize
    this._blockOffset = 0
    this._length = [0, 0, 0, 0]
    this._finalized = false
  }

  update = (data: Uint8Array): Ripemd160 => {
    if (this._finalized) throw new Error('Digest already called')

    // consume data
    const block = this._block
    let offset = 0
    while (this._blockOffset + data.length - offset >= this._blockSize) {
      for (let i = this._blockOffset; i < this._blockSize; ) block[i++] = data[offset++]
      this._update()
      this._blockOffset = 0
    }
    while (offset < data.length) block[this._blockOffset++] = data[offset++]

    // update length
    for (let j = 0, carry = data.length * 8; carry > 0; ++j) {
      this._length[j] += carry
      carry = (this._length[j] / 0x0100000000) | 0
      if (carry > 0) this._length[j] -= 0x0100000000 * carry
    }

    return this
  }

  digest = (): Uint8Array => {
    if (this._finalized) throw new Error('Digest already called')
    this._finalized = true

    const digest = this._digest()

    // reset state
    this._block.fill(0)
    this._blockOffset = 0
    for (let i = 0; i < 4; ++i) this._length[i] = 0

    return digest
  }

  private _update = () => {
    const words = new Array(16)
    const temp = new DataView(this._block.buffer)
    for (let j = 0; j < 16; ++j) words[j] = words[j] = temp.getInt32(j * 4, true)

    let al = this._a | 0
    let bl = this._b | 0
    let cl = this._c | 0
    let dl = this._d | 0
    let el = this._e | 0

    let ar = this._a | 0
    let br = this._b | 0
    let cr = this._c | 0
    let dr = this._d | 0
    let er = this._e | 0

    // computation
    for (let i = 0; i < 80; i += 1) {
      let tl
      let tr
      if (i < 16) {
        tl = fn1(al, bl, cl, dl, el, words[zl[i]], hl[0], sl[i])
        tr = fn5(ar, br, cr, dr, er, words[zr[i]], hr[0], sr[i])
      } else if (i < 32) {
        tl = fn2(al, bl, cl, dl, el, words[zl[i]], hl[1], sl[i])
        tr = fn4(ar, br, cr, dr, er, words[zr[i]], hr[1], sr[i])
      } else if (i < 48) {
        tl = fn3(al, bl, cl, dl, el, words[zl[i]], hl[2], sl[i])
        tr = fn3(ar, br, cr, dr, er, words[zr[i]], hr[2], sr[i])
      } else if (i < 64) {
        tl = fn4(al, bl, cl, dl, el, words[zl[i]], hl[3], sl[i])
        tr = fn2(ar, br, cr, dr, er, words[zr[i]], hr[3], sr[i])
      } else {
        // if (i<80) {
        tl = fn5(al, bl, cl, dl, el, words[zl[i]], hl[4], sl[i])
        tr = fn1(ar, br, cr, dr, er, words[zr[i]], hr[4], sr[i])
      }

      al = el
      el = dl
      dl = rotl(cl, 10)
      cl = bl
      bl = tl

      ar = er
      er = dr
      dr = rotl(cr, 10)
      cr = br
      br = tr
